  // People
  Insured: "Insured",
  "The Insured": "Insured",
  "Section 1 – Insured Person": "Insured",
  "Insured & Contact Details": "Insured",
  Driver: "Driver",
  "The Driver at the Time of the Accident": "Driver",
  Passengers: "Passengers",
  "Passengers (Insured Vehicle)": "Passengers",
  Owner: "Owner",
  "Finance Company": "Finance",
  "Section B: Main Member's Details": "Member",
  "Section C: Deceased's Details": "Deceased",
  "Section E: Beneficiary's Details": "Beneficiary",
  Relationship: "Relationship",

  // Third parties and witnesses
  "Other Party": "Third party",
  "Other Party — Other Vehicles": "Third party",
  "If Loss / Damage Was Caused By Another Party": "Third party",
  "Other Party — Personal Injuries": "Injuries",
  "Personal Injuries": "Injuries",
  "Personal Injuries (Other Than in Insured's Vehicle)": "Injuries",
  Witnesses: "Witnesses",
  "Independent Witnesses": "Witnesses",

  // Vehicle and incident
  Vehicle: "Vehicle",
  "The Vehicle": "Vehicle",
  Damage: "Damage",
  Accident: "Accident",
  "The Accident": "Accident",
  "Accident Details": "Accident",
  "Description of Accident": "Accident",
  Incident: "Incident",
  Theft: "Theft",
  "Theft (vehicle theft claims only)": "Theft",
  "Licence Inspected": "Licence",
  "Property Other Than Vehicles": "Property",
  "Property Damage": "Property",

  // Loss / property
  Occurrence: "Occurrence",
  "Loss / Damage Occurrence": "Occurrence",
  "Loss / Damage Address": "Address",
  "Cause of Loss / Damage": "Cause",
  "Previous Loss / Damage": "History",
  Premises: "Premises",
