  "Section 2 – Death / Personal Accident": "Accident",
  "Section 3 – Medical Claims": "Medical",
  "Section 4 – Baggage, Cash and Travel Documents": "Baggage",
  "Missing / Damaged Articles Schedule": "Articles",
  "Section 5 – Cancellation, Curtailment or Alteration": "Cancellation",
  "Section 6 – Travel Delay": "Delay",
  "Section 7 – Personal Liability": "Liability",

  // Payment and sign-off
  "Payment Method": "Payment",
